-- 047_field_crop_organic_plan.sql
-- 1. แผน "ปุ๋ยเคมีร่วมกับปุ๋ยอินทรีย์" (organic70) ของพืชไร่ ข้าว ผัก 20 ชนิด
--    ที่มา: ไฟล์ "คำนวนปุ๋ยพืชไร่และผัก ไม่ตามกรม 20.11.69_.xlsx" — กรมฯ ไม่มีตารางนี้ ไฟล์คำนวณจากอัตราแนะนำของกรมฯ
--      ปุ๋ยไนโตรเจนลดเหลือ 70% (หักไนโตรเจนจาก 18-46-0 ก่อน) ฟอสฟอรัส/โพแทสเซียมเต็มอัตรา
--      แบ่งยูเรียครั้งละครึ่ง ฟอสฟอรัสใส่ครั้งที่ 1 โพแทสเซียมใส่ครั้งที่ 1 (พริก มะเขือ มะเขือเทศ กระเจี๊ยบเขียว
--      หน่อไม้ฝรั่ง แบ่งครึ่ง) ปุ๋ยอินทรีย์ = ยูเรียที่ลดลง x 230 กก. — ปัดเป็นจำนวนเต็มตามที่ไฟล์แสดง
--    ต่างจากไฟล์: กระเจี๊ยบเขียวคำนวณใหม่ตามวิธีเดียวกัน (สูตรส่วน 70% ในไฟล์อ้างช่องผิด)
--      อ้อย OM < 0.75 ใช้กรณีปกติ (N 27) ไม่ใช้กรณีใส่กากตะกอนหม้อกรอง
--      ถั่ว ใช้ชื่อระยะ "ไม่ใช้ปุ๋ยชีวภาพไรโซเบียม" (ปุ๋ยอินทรีย์ทดแทนยูเรีย ซึ่งใส่เฉพาะกรณีนี้)
--      หน่อไม้ฝรั่ง ระยะเก็บเกี่ยว/พักต้น ใช้ค่าตามตารางปุ๋ยเคมีของกรมฯ (ไฟล์เขียนพักต้นครั้งที่ 2 เป็น 46-0-0)
--    ช่วงค่าดินใช้ตัวเลขเดียวกับตารางปุ๋ยเคมี (straight) ของพืชนั้น — 2625 แถว
-- 2. อัตรา K2O ที่ไม่ตรงกับตารางผสมปุ๋ยของกรมฯ และไฟล์ใหม่
--    พริก มะเขือ มะเขือเทศ กระเจี๊ยบเขียว K > 100: 4 -> 6 กก./ไร่ (ตารางผสมปุ๋ยใช้ 0-0-60 10 กก. = K2O 6)
--    หน่อไม้ฝรั่ง K 60-100: 12 -> 16 กก./ไร่ (ตารางผสมปุ๋ยใช้ 0-0-60 13+13 กก.)
-- 3. อ้อยปลูก/อ้อยตอ OM < 0.75: แผนปุ๋ยเคมีมี 2 กรณีปนกัน หน้าจอแสดงทุกสูตรซ้ำ 2 บรรทัด
--    เก็บกรณีปกติ (N 27 ตรงกับข้อ 6 — ปริมาณมากกว่าในแต่ละคู่) ลบกรณีใส่กากตะกอนหม้อกรอง (N 21/18)
--    หมายเหตุของพืชแนะนำเรื่องกากตะกอนหม้อกรองไว้แล้ว
-- รันซ้ำได้

-- ---------------------------------------------------------------- 1
delete from public.crop_fertilizer_plan p
 using public.crops c
 where p.crop_id = c.id and p.use_type = 'organic70'
   and trim(c.name) in ('อ้อยปลูก', 'อ้อยตอ', 'มันสำปะหลัง', 'ข้าวโพดเลี้ยงสัตว์', 'ข้าวโพดฝักสด', 'ถั่ว', 'ข้าวไวแสง', 'ข้าวไม่ไวแสง', 'หน่อไม้ฝรั่ง', 'มันฝรั่ง', 'มันเทศ', 'เผือก', 'กระเทียม', 'หอมแดง', 'หอมหัวใหญ่', 'พริก', 'มะเขือ', 'มะเขือเทศ', 'กระเจี๊ยบเขียว', 'ผัก');

