  join public.crops c on trim(c.name) = v.crop;

-- ---------------------------------------------------------------- 2
update public.fertilizer_recommendations r
   set target_k2o = 6
  from public.crops c
 where r.crop_id = c.id and trim(c.name) in ('พริก', 'มะเขือ', 'มะเขือเทศ', 'กระเจี๊ยบเขียว')
   and r.k_min > 100 and r.target_k2o = 4;

update public.fertilizer_recommendations r
   set target_k2o = 16
  from public.crops c
 where r.crop_id = c.id and trim(c.name) = 'หน่อไม้ฝรั่ง'
   and r.k_min = 60 and r.k_max = 100 and r.target_k2o = 12;

-- ---------------------------------------------------------------- 3
delete from public.crop_fertilizer_plan p
 using (
   select p2.id,
          row_number() over (
            partition by p2.crop_id, p2.use_type, p2.om_min, p2.om_max, p2.p_min, p2.p_max,
                         p2.k_min, p2.k_max, p2.stage_order, p2.grade
            order by p2.amount desc, p2.id) as rn
     from public.crop_fertilizer_plan p2
     join public.crops c on c.id = p2.crop_id
    where trim(c.name) in ('อ้อยปลูก', 'อ้อยตอ') and p2.use_type in ('straight', 'compound')
 ) d
 where p.id = d.id and d.rn > 1;
